import React, { useState } from 'react';

const characters = [
  'Prof. Plum',
  'Mrs. Peacock',
  'Mr. Green',
  'Miss Scarlet',
  'Col. Mustard',
  'Mrs. White',
];
const weapons = [
  'Candlestick',
  'Knife',
  'Lead Pipe',
  'Revolver',
  'Rope',
  'Wrench',
];
const rooms = [
  'Study',
  'Hall',
  'Lounge',
  'Library',
  'Billiard Room',
  'Dining Room',
  'Conservatory',
  'Ballroom',
  'Kitchen',
];

function ActionPanel({
  gameState,
  playerId,
  isMyTurn,
  currentPlayer,
  onSuggestion,
  onAccusation,
  onMove,
}) {
  const [suggestionForm, setSuggestionForm] = useState({
    character: '',
    weapon: '',
  });

  const [accusationForm, setAccusationForm] = useState({
    character: '',
    weapon: '',
    room: '',
  });

  const [showSuggestionForm, setShowSuggestionForm] = useState(false);
  const [showAccusationForm, setShowAccusationForm] = useState(false);

  if (!gameState || !gameState.gameStarted) {
    return (
      <div className="action-panel">
        <h3>Actions</h3>
        <p>Game not started yet. Wait for all players to be ready.</p>
      </div>
    );
  }

  const canMakeSuggestion = () => {
    if (!isMyTurn || !currentPlayer) return false;

    // Can only make suggestion if in a room (not hallway)
    return !currentPlayer.location.includes('-');
  };

  const getCurrentRoom = () => {
    if (!currentPlayer || currentPlayer.location.includes('-')) return null;
    return gameState.board.rooms[currentPlayer.location]?.name;
  };

  const getValidMoves = () => {
    if (!currentPlayer || !isMyTurn) return [];

    const location = currentPlayer.location;
    const validMoves = [];

    if (location.includes('-')) {
      // In hallway - can move to connected rooms
      const hallway = gameState.board.hallways[location];
      if (hallway) {
        hallway.connects.forEach((roomId) => {
          const room = gameState.board.rooms[roomId];
          if (room) {
            validMoves.push({ id: roomId, name: room.name, type: 'room' });
          }
        });
      }
    } else {
      // In room - can move to connected hallways or secret passages
      const room = gameState.board.rooms[location];
      if (room) {
        // Add connected hallways that are not occupied
        room.doors.forEach((hallwayId) => {
          const hallway = gameState.board.hallways[hallwayId];
          if (hallway && !hallway.player) {
            validMoves.push({
              id: hallwayId,
              name: hallway.name,
              type: 'hallway',
            });
          }
        });

        // Add secret passages
        if (gameState.board.secretPassages[location]) {
          const targetRoom = gameState.board.secretPassages[location];
          const targetRoomData = gameState.board.rooms[targetRoom];
          if (targetRoomData) {
            validMoves.push({
              id: targetRoom,
              name: `${targetRoomData.name} (Secret Passage)`,
              type: 'room',
            });
          }
        }
      }
    }

    return validMoves;
  };

  const handleSuggestionSubmit = (e) => {
    e.preventDefault();
    if (suggestionForm.character && suggestionForm.weapon) {
      onSuggestion(suggestionForm);
      setSuggestionForm({ character: '', weapon: '' });
      setShowSuggestionForm(false);
    }
  };

  const handleAccusationSubmit = (e) => {
    e.preventDefault();
    if (
      accusationForm.character &&
      accusationForm.weapon &&
      accusationForm.room
    ) {
      onAccusation(accusationForm);
      setAccusationForm({ character: '', weapon: '', room: '' });
      setShowAccusationForm(false);
    }
  };

  const validMoves = getValidMoves();
  const currentRoom = getCurrentRoom();

  return (
    <div className="action-panel">
      <h3>Actions</h3>

      {!isMyTurn && (
        <p>
          Waiting for {gameState.players[gameState.currentPlayer]?.name}'s
          turn...
        </p>
      )}

      {isMyTurn && (
        <div>
          <h4>Your Turn</h4>

          {/* Movement Options */}
          {validMoves.length > 0 && (
            <div className="movement-section">
              <h5>Available Moves:</h5>
              <div className="moves-list">
                {validMoves.map((move) => (
                  <button
                    key={move.id}
                    className="move-option"
                    onClick={() => onMove(move.id)}
                  >
                    Move to {move.name}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Suggestion Form */}
          {canMakeSuggestion() && (
            <div className="suggestion-section">
              <button
                className="btn"
                onClick={() => setShowSuggestionForm(!showSuggestionForm)}
              >
                {showSuggestionForm ? 'Cancel Suggestion' : 'Make Suggestion'}
              </button>

              {showSuggestionForm && (
                <form
                  className="suggestion-form"
                  onSubmit={handleSuggestionSubmit}
                >
                  <h5>Make Suggestion in {currentRoom}</h5>

                  <div className="form-group">
                    <label>Character:</label>
                    <select
                      value={suggestionForm.character}
                      onChange={(e) =>
                        setSuggestionForm((prev) => ({
                          ...prev,
                          character: e.target.value,
                        }))
                      }
                      required
                    >
                      <option value="">Select character</option>
                      {characters.map((char) => (
                        <option key={char} value={char}>
                          {char}
                        </option>
                      ))}
                    </select>
                  </div>

                  <div className="form-group">
                    <label>Weapon:</label>
                    <select
                      value={suggestionForm.weapon}
                      onChange={(e) =>
                        setSuggestionForm((prev) => ({
                          ...prev,
                          weapon: e.target.value,
                        }))
                      }
                      required
                    >
                      <option value="">Select weapon</option>
                      {weapons.map((weapon) => (
                        <option key={weapon} value={weapon}>
                          {weapon}
                        </option>
                      ))}
                    </select>
                  </div>

                  <button type="submit" className="btn">
                    Submit Suggestion
                  </button>
                </form>
              )}
            </div>
          )}

          {/* Accusation Form */}
          <div className="accusation-section">
            <button
              className="btn"
              onClick={() => setShowAccusationForm(!showAccusationForm)}
            >
              {showAccusationForm ? 'Cancel Accusation' : 'Make Accusation'}
            </button>

            {showAccusationForm && (
              <form
                className="accusation-form"
                onSubmit={handleAccusationSubmit}
              >
                <h5>Make Accusation</h5>
                <p>
                  <small>Warning: Wrong accusation eliminates you!</small>
                </p>

                <div className="form-group">
                  <label>Character:</label>
                  <select
                    value={accusationForm.character}
                    onChange={(e) =>
                      setAccusationForm((prev) => ({
                        ...prev,
                        character: e.target.value,
                      }))
                    }
                    required
                  >
                    <option value="">Select character</option>
                    {characters.map((char) => (
                      <option key={char} value={char}>
                        {char}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label>Weapon:</label>
                  <select
                    value={accusationForm.weapon}
                    onChange={(e) =>
                      setAccusationForm((prev) => ({
                        ...prev,
                        weapon: e.target.value,
                      }))
                    }
                    required
                  >
                    <option value="">Select weapon</option>
                    {weapons.map((weapon) => (
                      <option key={weapon} value={weapon}>
                        {weapon}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label>Room:</label>
                  <select
                    value={accusationForm.room}
                    onChange={(e) =>
                      setAccusationForm((prev) => ({
                        ...prev,
                        room: e.target.value,
                      }))
                    }
                    required
                  >
                    <option value="">Select room</option>
                    {rooms.map((room) => (
                      <option key={room} value={room}>
                        {room}
                      </option>
                    ))}
                  </select>
                </div>

                <button type="submit" className="btn">
                  Submit Accusation
                </button>
              </form>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default ActionPanel;
